const TERMINAL_STATES: ReadonlySet<string> = new Set([
  'completed',
  'failed',
  'canceled',
  'rejected',
]);

/**
 * Determines whether a task state represents a terminal (final) state.
 * @param state The task state string, or undefined.
 * @returns True if the state is terminal, false otherwise (including undefined).
 */
export function isTerminalState(state: string | undefined): boolean {
  if (!state) {
    return false;
  }
  return TERMINAL_STATES.has(state);
}

/**
 * Extracts contextId and taskId from a Message, Task, or streaming update event.
 * Follows the pattern from the A2A CLI sample to maintain conversational continuity.
 *
 * The returned `clearTaskId` flag indicates whether the caller should drop the
 * cached taskId so that the next interaction starts a fresh task. It is set to
 * true whenever the response reflects a terminal task state.
 */
export function extractIdsFromResponse(result: A2AStreamEvent): {
  contextId?: string;
  taskId?: string;
  clearTaskId: boolean;
} {
  let contextId: string | undefined;
  let taskId: string | undefined;
  let state: string | undefined;

  switch (result.kind) {
    case 'message':
      contextId = result.contextId;
      taskId = result.taskId;
      break;
    case 'task':
      contextId = result.contextId;
      taskId = result.id;
      state = result.status?.state;
      break;
    case 'status-update':
      contextId = result.contextId;
      taskId = result.taskId;
      state = result.status?.state;
      break;
    case 'artifact-update':
      contextId = result.contextId;
      taskId = result.taskId;
      break;
    default:
      break;
  }

  return { contextId, taskId, clearTaskId: isTerminalState(state) };
}

