  private readonly messages: string[] = [];
  // Artifact content keyed by artifact ID, preserving first-seen ordering.
  private readonly artifacts = new Map<string, { name?: string; text: string }>();
  private readonly artifactOrder: string[] = [];

  /**
   * Processes a single streaming event, updating the reassembled state.
